from pathlib import Path
import json,random
from PIL import Image,ImageDraw
ROOT=Path(__file__).resolve().parents[1];RES=ROOT/'src/main/resources';A=RES/'assets/bunnidogs';D=RES/'data/bunnidogs'
def write(root,path,obj):
 p=root/path;p.parent.mkdir(parents=True,exist_ok=True);p.write_text(json.dumps(obj,indent=2,ensure_ascii=False)+'\n')
def model(name,parent='minecraft:item/generated'):
 write(A,Path('models/item')/(name+'.json'),{'parent':parent,'textures':{'layer0':'bunnidogs:item/'+name}});write(A,Path('items')/(name+'.json'),{'model':{'type':'minecraft:model','model':'bunnidogs:item/'+name}})
colors=['#a6d6ec','#a6c171','#ee9071','#d3a1df','#e8c77c'];rng=random.Random(91241)
# All UVs use separate strips; opaque pixels throughout the atlas avoid missing underside faces.
atlas=Image.new('RGBA',(128,32));ad=ImageDraw.Draw(atlas)
for i,color in enumerate(colors+['#6a5853','#d9bd7b','#fff1be']):
 rgb=Image.new('RGB',(1,1),color).getpixel((0,0))
 for x in range(i*16,i*16+16):
  for y in range(32):
   n=rng.randint(-8,8)+(14 if y%8==1 else 0);atlas.putpixel((x,y),tuple(max(0,min(255,c+n)) for c in rgb)+(255,))
atlas.save(A/'textures/entity/crowned_apex.png')
# Geometry stays separate from the approved animal sculpt. Data also drives the preview.
boxes=[{'part':'head','box':[-4.8,-5.7,-3.7,9.6,1,1.4],'uv':96},
       {'part':'head','box':[-4.8,-5.5,-2.3,1,1,5.4],'uv':96},
       {'part':'head','box':[3.8,-5.5,-2.3,1,1,5.4],'uv':96}]
for i in range(5):
 h=[2.3,3.3,4.3,3.3,2.3][i]
 for width,top,bottom in [(1.6,h*.55,0),(1.1,h*.86,h*.55),(.55,h,h*.86)]:
  boxes.append({'part':'head','box':[-4+i*2-width/2,-5.7-top,-3.0-width/2,width,top-bottom,width],'uv':i*16})
for i in range(5):
 boxes.append({'part':'body','box':[-1.8,-4.4,-2.2+i*1.65,3.6,1.4,1.2],'uv':96})
 boxes.append({'part':'body','box':[-1.1,-5,-1.95+i*1.65,2.2,1.1,.7],'uv':i*16})
write(ROOT,Path('art/crown_geometry.json'),boxes)
source='''// Generated by art/gen_crown.py. Separate crown/organ geometry preserves the animal sculpt.
package com.bunnidogs.mod.client.model;
import net.minecraft.client.model.geom.builders.*;
public final class CrownModelLayer {
    public static LayerDefinition createLayer() {
        var mesh=new MeshDefinition();var animal=BunnidogModelLayer.createBodyLayer().bakeRoot();
'''
for part in ['head','body']:
 chain='CubeListBuilder.create()'
 for row in boxes:
  if row['part']==part:chain+=f'.texOffs({row["uv"]},0).addBox('+','.join(str(n)+'F' for n in row['box'])+')'
 source+=f'        mesh.getRoot().addOrReplaceChild("{part}",{chain},animal.getChild("{part}").getInitialPose());\n'
source+='        return LayerDefinition.create(mesh,128,32);\n    }\n}\n'
(ROOT/'src/main/java/com/bunnidogs/mod/client/model/CrownModelLayer.java').write_text(source)
# Physical seals use the actual three key colors and sockets; never a new tutorial UI.
variants={}
for wing in range(4):
 for state in range(3):
  for sockets in (range(8) if wing==3 else [0]):
   name=f'crown_seal_{wing}_{state}_{sockets}'
   im=Image.new('RGB',(16,16),'#394f4c');d=ImageDraw.Draw(im);d.rectangle((0,0,15,15),outline='#a3a78d');d.rectangle((2,2,13,13),outline='#253732')
   if wing<3:
    d.polygon([(8,3),(12,8),(8,12),(3,8)],fill=colors[wing],outline='#e8d6a1')
    if state==1:d.rectangle((5,5,10,10),outline='#fff1cf')
    if state==2:d.line((4,8,7,11,12,5),fill='#fff4cc',width=2)
   else:
    for i in range(3):d.rectangle((2+i*4,6,4+i*4,10),fill=colors[i] if sockets&(1<<i) else '#172a29',outline='#c1ab78')
    d.line((3,3,5,4,8,2,11,4,13,3),fill='#fae0a2')
   path=A/'textures/block'/f'{name}.png';path.parent.mkdir(parents=True,exist_ok=True);im.save(path)
   write(A,Path('models/block')/(name+'.json'),{'parent':'minecraft:block/cube_all','textures':{'all':'bunnidogs:block/'+name}})
   variants[f'wing={wing},state={state}'+(f',sockets={sockets}' if wing==3 else '')]={'model':'bunnidogs:block/'+name}
write(A,Path('blockstates/crown_seal.json'),{'variants':variants})
