  im=Image.open(A/'textures/item'/f'{base}.png').convert('RGBA').resize((32,32),Image.Resampling.NEAREST);d=ImageDraw.Draw(im);d.polygon([(16,5),(20,10),(16,15),(12,10)],fill='#fff0c1',outline='#b38858');d.line((11,3,16,1,21,3),fill='#f9d68e',width=2)
