# Carry every native armor/enchantment family forward, including armor trim tags.
for p in (RES/'data/minecraft/tags/item').rglob('*.json'):
 o=json.loads(p.read_text());vals=o.get('values',[]);extra=[]
 for v in vals:
  if isinstance(v,str):
   if v.startswith('bunnidogs:heartbound_'):extra.append(v.replace('heartbound_','sovereign_'))
   if v=='bunnidogs:apex_wing_harness':extra.append('bunnidogs:sovereign_elytra')
 if p.name=='durability.json' and p.parent.name=='enchantable':extra+=['bunnidogs:sovereign_lance','bunnidogs:concord_standard']
